// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

/**
* Interface defining `factory` options.
*/
interface Options {
	/**
	* Pseudorandom number generator seed.
	*/
	seed?: number | bigint;

	/**
	* Pseudorandom number generator state.
	*/
	state?: Array<bigint>;

	/**
	* Specifies whether to copy a provided pseudorandom number generator state.
	*/
	copy?: boolean;
}

/**
* Interface for PRNG properties and methods.
*/
interface PRNG {
	/**
	* Generator name.
	*/
	readonly NAME: string;

	/**
	* PRNG seed.
	*/
	readonly seed: bigint;

	/**
	* PRNG state.
	*/
	state: Array<bigint>;

	/**
	* Serializes the pseudorandom number generator as a JSON object.
	*
	* @returns JSON representation
	*/
	toJSON(): {
		type: string;
		name: string;
		state: Array<bigint>;
		params: Array<unknown>;
	};
}

/**
* Interface for generating pseudorandom 64-bit unsigned integers.
*/
interface NullaryFunction extends PRNG {
	/**
	* Returns a pseudorandom 64-bit unsigned integer.
	*
	* @returns pseudorandom number
	*/
	(): bigint;

	/**
	* Returns a pseudorandom number on the interval `[0,1)`.
	*
	* @returns pseudorandom number
	*/
	normalized(): number;

	/**
	* Returns a copy of the PRNG.
	*
	* @returns copy of the PRNG
	*/
	copy(): NullaryFunction;
}

/**
* Interface for the xorshift128+ PRNG factory.
*/
/**
	* Returns a xorshift128+ pseudorandom number generator.
	*
	* @param options - function options
	* @param options.seed - pseudorandom number generator seed
	* @param options.state - pseudorandom number generator state
	* @param options.copy - boolean indicating whether to copy a provided pseudorandom number generator state (default: true)
	* @throws must provide valid options
	* @returns pseudorandom number generator
	*
	* @example
	* var rng = factory();
	* var v = rng();
	* // returns <bigint>
	*
	* @example
	* var rng = factory({
	*     'seed': BigInt(12345)
	* });
	* var v = rng();
	* // returns <bigint>
	*/
type Factory = ( options?: Options ) => NullaryFunction;

/**
* Returns a xorshift128+ pseudorandom number generator.
*
* ## Notes
*
* -   This pseudorandom number generator (PRNG) is a 128-bit xorshift PRNG with a period of approximately 2^128.
* -   The generator produces 64-bit pseudorandom integers using BigInt arithmetic.
* -   The generator is suitable for general-purpose use and Monte Carlo simulations.
* -   For cryptographic applications, use a cryptographically secure pseudorandom number generator (CSPRNG).
*
* @param options - function options
* @param options.seed - pseudorandom number generator seed
* @param options.state - pseudorandom number generator state
* @param options.copy - boolean indicating whether to copy a provided pseudorandom number generator state (default: true)
* @throws must provide valid options
* @returns pseudorandom number generator
*
* @example
* var rng = factory();
* var v = rng();
* // returns <bigint>
*
* @example
* var rng = factory();
* var v = rng.normalized();
* // returns <number>
*
* @example
* var rng = factory({
*     'seed': BigInt(12345)
* });
* var v = rng();
* // returns <bigint>
*/
declare var factory: Factory;


// EXPORTS //

export = factory;

